import { StyleSheet, } from 'react-native';

const styles = StyleSheet.create({
    container: {
        alignItems: 'center',
        position: 'absolute',
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        justifyContent: 'space-around',

    },

    listText: {
        fontSize: 40,
        color: '#000',
        backgroundColor: '#fff',
        padding: 5,
        borderRadius: 10,
        margin: 20

    },

    textLoadPopUp: {
        color: '#fff',
        fontSize: 30,
        textAlign: 'center',
        marginHorizontal: 10
    },

    ActivityIndicator: {
        marginTop: 10,
        marginBottom: 20
    },

    containerButtonComprar: {
        backgroundColor: '#26A744',
        borderRadius: 15,
        width: 230,
        padding: 10
    },

    textButtonComprar: {
        color: '#fff',
        fontSize: 30,
        textAlign: 'center'
    },

    containerButtonAddCart: {
        backgroundColor: '#17A2B7',
        borderRadius: 15,
        width: 230,
        padding: 10,
        margin: 10
    },

    textButtonAddCart: {
        color: '#fff',
        fontSize: 30,
        textAlign: 'center'
    },
});
export { styles };
